};

// Producer 생성 함수
async function createProducer() {
    try {
        //console.log('�� Producer 생성 시작');

        if (!sendTransport) {
            //console.error('❌ Send Transport가 없습니다');
            return;
        }

        // Transport 연결 상태 확인 (PeerConnection 접근 방법 개선)
        let sendPeerConnection = sendTransport._pc || 
                                sendTransport._handler?.pc || 
                                sendTransport.handler?.pc;

        //console.log('������ Send Transport 상태 확인:', {
            hasPeerConnection: !!sendPeerConnection,
            connectionState: sendPeerConnection?.connectionState,
            iceConnectionState: sendPeerConnection?.iceConnectionState,
            signalingState: sendPeerConnection?.signalingState,
            transportClosed: sendTransport.closed,
            transportConnectionState: sendTransport.connectionState
        });

        // Transport가 연결될 때까지 대기
        if (sendPeerConnection && sendPeerConnection.connectionState !== 'connected') {
            //console.log('⏳ Send Transport 연결 대기 중... 현재 상태:', sendPeerConnection.connectionState);
            await waitForTransportConnection(sendTransport);
        } else if (!sendPeerConnection) {
            //console.log('⚠️ PeerConnection을 찾을 수 없음. Transport 강제 연결 시도');
            // PeerConnection이 없어도 계속 진행 (Transport 이벤트로 연결될 수 있음)
        }

        const stream = await navigator.mediaDevices.getUserMedia({ 
            video: true, 
            audio: true 
        });

        localVideo.srcObject = stream;

        // 비디오 track으로 Producer 생성
        const videoTrack = stream.getVideoTracks()[0];
        const audioTrack = stream.getAudioTracks()[0];

        //console.log('������ Track 정보:', {
            video: {
                id: videoTrack.id,
                kind: videoTrack.kind,
                enabled: videoTrack.enabled,
                readyState: videoTrack.readyState
            },
            audio: {
                id: audioTrack.id,
                kind: audioTrack.kind,
                enabled: audioTrack.enabled,
                readyState: audioTrack.readyState
            }
        });

        // Video Producer 생성
        const videoProducer = await sendTransport.produce({
            track: videoTrack,
            encodings: [{
                maxBitrate: 100000
            }],
            codecOptions: {
                videoGoogleStartBitrate: 1000
            }
        });

        // Audio Producer 생성
        const audioProducer = await sendTransport.produce({
            track: audioTrack
        });

        //console.log('✅ Producer 생성 완료:', {
            video: {
                id: videoProducer.id,
                kind: videoProducer.kind,
                paused: videoProducer.paused,
                closed: videoProducer.closed
            },
            audio: {
                id: audioProducer.id,
                kind: audioProducer.kind,
                paused: audioProducer.paused,
                closed: audioProducer.closed
            }
        });

        // Producer 상태 모니터링
        videoProducer.on('transportclose', () => {
            //console.log('������ Video Producer transport closed');
        });

        videoProducer.on('trackended', () => {
            //console.log('������ Video Producer track ended');
        });

        audioProducer.on('transportclose', () => {
            //console.log('������ Audio Producer transport closed');
        });

        audioProducer.on('trackended', () => {
            //console.log('������ Audio Producer track ended');
        });

        // Producer 생성 후 잠시 대기
        //console.log('⏳ Producer 안정화 대기 중...');
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Transport 상태 재확인
        //console.log('������ Producer 생성 후 Transport 상태:', {
            connectionState: sendTransport._pc?.connectionState,
            iceConnectionState: sendTransport._pc?.iceConnectionState,
            senders: sendTransport._pc?.getSenders()?.length || 0
        });

        // 서버에 Producer 생성 알림
        mediasoupSocket.emit('newProducer', {
            socketId: mediasoupSocket.id,
            userName: currentUser
        });

        //console.log('������ newProducer 이벤트 전송 완료');

    } catch (error) {
        //console.error('❌ Producer 생성 실패:', error);
        alert('카메라/마이크 접근에 실패했습니다: ' + error.message);
    }
}

// Transport 연결 대기 함수
async function waitForTransportConnection(transport) {
    return new Promise((resolve, reject) => {
        let attemptCount = 0;
        const maxAttempts = 60; // 30초 대기 (500ms * 60)

        const checkConnection = () => {
            attemptCount++;

            // PeerConnection 찾기 (여러 방법 시도)
            const pc = transport._pc || 
                      transport._handler?.pc || 
                      transport.handler?.pc;

            if (pc && pc.connectionState === 'connected') {
                //console.log('✅ Transport 연결 완료');
                resolve();
            } else if (pc && pc.connectionState === 'failed') {
                //console.error('❌ Transport 연결 실패');
                reject(new Error('Transport connection failed'));
            } else if (attemptCount >= maxAttempts) {
                //console.warn('⚠️ Transport 연결 대기 시간 초과. 현재 상태로 진행');
                resolve(); // 시간 초과 시에도 진행
            } else {
                //console.log(`⏳ Transport 연결 상태 (${attemptCount}/${maxAttempts}):`, {
                    hasPeerConnection: !!pc,
                    connectionState: pc?.connectionState,
                    transportConnectionState: transport.connectionState,
                    transportClosed: transport.closed
                });
                setTimeout(checkConnection, 500);
            }
        };
        checkConnection();
    });
}

// ... existing code ...

        // Consumer 생성 함수
        async function createConsumer(producerId, userName) {
            try {
                //console.log('������ Consumer 생성 시작:', { producerId, userName });

                if (!recvTransport) {
                    //console.error('❌ Receive Transport가 없습니다');
                    return;
                }

                // Receive Transport 연결 상태 확인 (PeerConnection 접근 방법 개선)
                let recvPeerConnection = recvTransport._pc || 
                                        recvTransport._handler?.pc || 
                                        recvTransport.handler?.pc;

                //console.log('������ Receive Transport 상태 확인:', {
                    hasPeerConnection: !!recvPeerConnection,
                    connectionState: recvPeerConnection?.connectionState,
                    iceConnectionState: recvPeerConnection?.iceConnectionState,
                    signalingState: recvPeerConnection?.signalingState,
                    transportClosed: recvTransport.closed,
                    transportConnectionState: recvTransport.connectionState,
                    receivers: recvPeerConnection?.getReceivers()?.length || 0
                });

                // Transport가 연결될 때까지 대기
                if (recvPeerConnection && recvPeerConnection.connectionState !== 'connected') {
                    //console.log('⏳ Receive Transport 연결 대기 중... 현재 상태:', recvPeerConnection.connectionState);
                    await waitForTransportConnection(recvTransport);
                } else if (!recvPeerConnection) {
                    //console.log('⚠️ Receive PeerConnection을 찾을 수 없음. Consumer 생성 계속 진행');
                }

                //console.log('������ 서버에 Consumer 생성 요청');
                const response = await new Promise((resolve, reject) => {
                    const timeout = setTimeout(() => {
                        reject(new Error('Consumer 생성 요청 시간 초과'));
                    }, 15000);

                    mediasoupSocket.emit('consume', {
                        rtpCapabilities: device.rtpCapabilities,
                        producerId: producerId
                    }, (response) => {
                        clearTimeout(timeout);

                        //console.log('������ 서버 응답 수신:', {
                            success: response.success,
                            hasError: !!response.error,
                            error: response.error,
                            hasConsumerId: !!response.consumerId,
                            consumerId: response.consumerId,
                            kind: response.kind,
                            hasRtpParameters: !!response.rtpParameters
                        });

                        if (!response.success) {
                            //console.error('❌ 서버에서 Consumer 생성 실패:', response.error);
                            reject(new Error(response.error || 'Consumer 생성 실패'));
                        } else if (!response.consumerId) {
                            //console.error('❌ 서버 응답에 consumerId가 없음:', response);
                            reject(new Error('Consumer ID가 없습니다'));
                        } else {
                            //console.log('✅ 서버에서 Consumer 생성 성공');
                            resolve(response);
                        }
                    });
                });

                //console.log('������ Consumer 생성 응답:', response);

                // Consumer 생성
                const consumer = await recvTransport.consume({
                    id: response.consumerId,
                    producerId: producerId, // 원래 요청한 producerId 사용
                    kind: response.kind,
                    rtpParameters: response.rtpParameters
                });

                //console.log('✅ Consumer 생성 완료:', {
                    id: consumer.id,
                    kind: consumer.kind,
                    producerId: consumer.producerId,
                    paused: consumer.paused,
                    closed: consumer.closed
                });

                // Consumer 생성 후 Transport 상태 재확인
                //console.log('������ Consumer 생성 후 Transport 상태:', {
                    connectionState: recvTransport._pc?.connectionState,
                    iceConnectionState: recvTransport._pc?.iceConnectionState,
                    receivers: recvTransport._pc?.getReceivers()?.length || 0
                });

                // Consumer resume
                //console.log('▶️ Consumer resume 시작');
                await new Promise((resolve, reject) => {
                    const timeout = setTimeout(() => {
                        //console.warn('⚠️ Consumer resume 시간 초과. 계속 진행합니다.');
                        resolve();
                    }, 10000);

                    mediasoupSocket.emit('resumeConsumer', {
                        consumerId: consumer.id
                    }, (response) => {
                        clearTimeout(timeout);
                        if (response && response.success) {
                            //console.log('✅ Consumer resume 성공');
                            resolve();
                        } else {
                            //console.error('❌ Consumer resume 실패:', response?.error);
                            reject(new Error(response?.error || 'Consumer resume 실패'));
                        }
                    });
                });

                // Consumer 이벤트 리스너 설정
                consumer.on('transportclose', () => {
                    //console.log('������ Consumer transport closed');
                });

                consumer.on('producerclose', () => {
                    //console.log('������ Consumer producer closed');
                });

                consumer.on('trackended', () => {
                    //console.log('������ Consumer track ended');
                });

                // Consumer 저장
                consumers.set(consumer.id, {
                    consumer: consumer,
                    producerId: producerId,
                    userName: userName,
                    kind: response.kind
                });

                //console.log('✅ Consumer 저장 완료:', {
                    consumerId: consumer.id,
                    totalConsumers: consumers.size
                });

                // Consumer 안정화 대기
                //console.log('⏳ Consumer 안정화 대기 중...');
                await new Promise(resolve => setTimeout(resolve, 1000));

                // Transport에서 직접 MediaStream 추출 시도
                await extractMediaStreamFromTransport(recvTransport, consumer, userName);

            } catch (error) {
                //console.error('❌ Consumer 생성 실패:', error);
            }
        }

        // Transport에서 MediaStream 추출 함수
        async function extractMediaStreamFromTransport(transport, consumer, userName) {
            try {
                //console.log('������ Transport에서 MediaStream 추출 시도');

                // PeerConnection 찾기 (여러 방법 시도)
                const pc = transport._pc || 
                          transport._handler?.pc || 
                          transport.handler?.pc;

                if (!pc) {
                    //console.error('❌ PeerConnection을 찾을 수 없습니다:', {
                        transportKeys: Object.keys(transport),
                        hasHandler: !!transport._handler,
                        handlerKeys: transport._handler ? Object.keys(transport._handler) : null
                    });
                    return;
                }

                //console.log('������ PeerConnection 상태:', {
                    connectionState: pc.connectionState,
                    iceConnectionState: pc.iceConnectionState,
                    signalingState: pc.signalingState,
                    iceGatheringState: pc.iceGatheringState
                });

                // 모든 Receiver 확인
                const receivers = pc.getReceivers();
                //console.log('������ 총 RTP Receivers:', receivers.length);

                if (receivers.length === 0) {
                    //console.error('❌ RTP Receiver가 없습니다. Transport 연결 문제일 수 있습니다.');
                    return;
                }

                // 각 Receiver 상세 정보
                receivers.forEach((receiver, index) => {
                    //console.log(`������ Receiver ${index}:`, {
                        track: !!receiver.track,
                        trackKind: receiver.track?.kind,
                        trackId: receiver.track?.id,
                        trackEnabled: receiver.track?.enabled,
                        trackReadyState: receiver.track?.readyState,
                        trackMuted: receiver.track?.muted
                    });
                });

                // Live track 수집
                const liveTracks = receivers
                    .map(receiver => receiver.track)
                    .filter(track => track && track.readyState === 'live');

                //console.log(`������ Live track 개수: ${liveTracks.length}`);

                if (liveTracks.length > 0) {
                    const stream = new MediaStream(liveTracks);
                    //console.log('✅ MediaStream 생성 완료:', {
                        id: stream.id,
                        tracks: stream.getTracks().length,
                        videoTracks: stream.getVideoTracks().length,
                        audioTracks: stream.getAudioTracks().length
                    });

                    // 비디오 표시
                    displayRemoteVideo(stream, userName || 'Unknown');
                } else {
                    //console.log('⏳ Live track이 없습니다. 잠시 후 다시 시도합니다.');

                    // 3초 후 재시도
                    setTimeout(() => {
                        extractMediaStreamFromTransport(transport, consumer, userName);
                    }, 3000);
                }

            } catch (error) {
                //console.error('❌ MediaStream 추출 실패:', error);
            }
        }

// ===== MediaSoup 코드 주석 처리 끝 =====
*/

// ===== Simple WebRTC 관련 추가 함수들 =====

// 화상통화 나가기
scwin.leaveCall = function() {
    try {
        // 모든 P2P 연결 종료
        peerConnections.forEach((pc, userId) => {
            pc.close();
        });
        peerConnections.clear();

        // 로컬 스트림 정지
        if (localStream) {
            localStream.getTracks().forEach(track => track.stop());
            localStream = null;
        }

        // 비디오 요소 초기화
        const localVideo = document.getElementById("localVideo");
        if (localVideo) {
            localVideo.srcObject = null;
        }

        // 원격 비디오 제거
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (remoteVideosGrid) {
            remoteVideosGrid.innerHTML = '';
        }

        // 나가기 알림
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const leaveMessage = {
                type: 'leave-room',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName,
                timestamp: Date.now()
            };
            chatSocket.send(JSON.stringify(leaveMessage));
        }

        isJoined = false;
        dma_videoChat.set("isJoined", "false");

        // 내 비디오를 그리드에서 제거
        scwin.removeMyVideoFromGrid();

        scwin.updateControlButtons();
        scwin.addChatMessage("시스템", "화상통화를 나갔습니다. 카메라와 마이크가 꺼졌습니다.", false);

        //console.log("✅ 화상통화 종료 완료");

    } catch (error) {
        //console.error("❌ 화상통화 종료 실패:", error);
    }
};

// 음소거 토글
scwin.toggleMute = function() {
    if (localStream) {
        const audioTrack = localStream.getAudioTracks()[0];
        if (audioTrack) {
            audioTrack.enabled = !audioTrack.enabled;
            const muteBtn = document.getElementById("muteBtn");
            if (muteBtn) {
                muteBtn.textContent = audioTrack.enabled ? "MIC" : "음소거";
                muteBtn.classList.toggle("muted", !audioTrack.enabled);
            }

            // 그리드에 있는 내 비디오의 사용자 이름에 음소거 표시
            const myUserNameInGrid = document.querySelector('[data-username="나"] .remote-user-name');
            if (myUserNameInGrid) {
                if (audioTrack.enabled) {
                    myUserNameInGrid.style.background = '#FFB823';
                    myUserNameInGrid.textContent = `나 (${currentUser.userName})`;
                } else {
                    myUserNameInGrid.style.background = '#dc3545';
                    myUserNameInGrid.textContent = `나 (${currentUser.userName}) - 음소거`;
                }
            }

            //console.log("������ 마이크:", audioTrack.enabled ? "켜짐" : "꺼짐");
            scwin.addChatMessage("시스템", audioTrack.enabled ? "마이크를 켰습니다." : "마이크를 껐습니다.", false);
        }
    }
};

// 비디오 토글
scwin.toggleVideo = function() {
    if (localStream) {
        const videoTrack = localStream.getVideoTracks()[0];
        if (videoTrack) {
            videoTrack.enabled = !videoTrack.enabled;
            const videoBtn = document.getElementById("videoBtn");
            if (videoBtn) {
                videoBtn.textContent = videoTrack.enabled ? "CAM" : "CAM OFF";
                videoBtn.classList.toggle("off", !videoTrack.enabled);
            }

            // 그리드에 있는 내 비디오에도 반영
            const myVideoContainer = document.querySelector('[data-username="나"] .remote-video-player');
            if (myVideoContainer) {
                const myVideoInGrid = myVideoContainer.querySelector('video');
                if (videoTrack.enabled) {
                    if (myVideoInGrid) myVideoInGrid.style.display = 'block';
                    // 카메라 꺼짐 메시지 제거
                    const offMessage = myVideoContainer.querySelector('.camera-off-message');
                    if (offMessage) offMessage.remove();
                } else {
                    if (myVideoInGrid) myVideoInGrid.style.display = 'none';
                    // 카메라 꺼짐 메시지 표시
                    let offMessage = myVideoContainer.querySelector('.camera-off-message');
                    if (!offMessage) {
                        offMessage = document.createElement('div');
                        offMessage.className = 'camera-off-message';
                        offMessage.style.cssText = `
                            position: absolute;
                            top: 50%;
                            left: 50%;
                            transform: translate(-50%, -50%);
                            color: white;
                            font-size: 18px;
                            font-weight: bold;
                            text-align: center;
                            background: rgba(0,0,0,0.7);
                            padding: 10px;
                            border-radius: 8px;
                        `;
                        offMessage.textContent = '카메라 꺼짐';
                        myVideoContainer.appendChild(offMessage);
                    }
                }
            }

            //console.log("������ 카메라:", videoTrack.enabled ? "켜짐" : "꺼짐");
            scwin.addChatMessage("시스템", videoTrack.enabled ? "카메라를 켰습니다." : "카메라를 껐습니다.", false);
        }
    }
};

// 버튼 상태 업데이트
scwin.updateControlButtons = function() {
    const joinBtn = document.getElementById("joinBtn");
    const leaveBtn = document.getElementById("leaveBtn");
    const muteBtn = document.getElementById("muteBtn");
    const videoBtn = document.getElementById("videoBtn");

    if (isJoined) {
        if (joinBtn) joinBtn.style.display = "none";
        if (leaveBtn) leaveBtn.style.display = "inline-block";
        if (muteBtn) muteBtn.disabled = false;
        if (videoBtn) videoBtn.disabled = false;
    } else {
        if (joinBtn) joinBtn.style.display = "inline-block";
        if (leaveBtn) leaveBtn.style.display = "none";
        if (muteBtn) muteBtn.disabled = true;
        if (videoBtn) videoBtn.disabled = true;
    }
};

// 내 비디오를 그리드에 추가 (다른 참가자들과 동일한 레이아웃)
scwin.addMyVideoToGrid = function(stream) {
    try {
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (!remoteVideosGrid) {
            console.warn('⚠️ remoteVideosGrid를 찾을 수 없음');
            return;
        }

        // 기존에 내 비디오가 있는지 확인
        const existingMyVideo = remoteVideosGrid.querySelector('[data-username="나"]');
        if (existingMyVideo) {
            existingMyVideo.remove();
        }

        // 내 비디오 아이템 생성
        const videoItem = document.createElement('div');
        videoItem.className = 'remote-user-video';
        videoItem.setAttribute('data-username', '나');
        videoItem.setAttribute('data-userid', currentUser.userId);

        videoItem.innerHTML = `
            <div class="remote-video-wrapper">
                <div class="remote-video-player">
                    <video autoplay muted playsinline style="
                        width: 100%; 
                        height: 100%; 
                        object-fit: cover; 
                        border-radius: 8px;
                        border: 3px solid #FFB823;
                    "></video>
                </div>
                <div class="remote-user-name" style="
                    background: #FFB823;
                    color: white;
                    font-weight: bold;
                ">나 (${currentUser.userName})</div>
            </div>
        `;

        // 비디오 스트림 연결
        const video = videoItem.querySelector('video');
        if (video && stream) {
            video.srcObject = stream;
        }

        // 그리드의 첫 번째 위치에 추가 (내가 맨 앞에 표시)
        remoteVideosGrid.insertBefore(videoItem, remoteVideosGrid.firstChild);

        //console.log('✅ 내 비디오를 그리드에 추가 완료');
        scwin.addChatMessage("시스템", "내 비디오가 메인 화면에 표시됩니다.", false);

    } catch (error) {
        //console.error('❌ 내 비디오 그리드 추가 실패:', error);
    }
};

// 내 비디오를 그리드에서 제거
scwin.removeMyVideoFromGrid = function() {
    try {
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (!remoteVideosGrid) return;

        const myVideoItem = remoteVideosGrid.querySelector('[data-username="나"]');
        if (myVideoItem) {
            myVideoItem.remove();
            console.log('✅ 내 비디오를 그리드에서 제거 완료');
        }
    } catch (error) {
        console.error('❌ 내 비디오 그리드 제거 실패:', error);
    }
};

// 원격 사용자 제거
scwin.removeRemoteUser = function(userId) {
    try {
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (!remoteVideosGrid) {
            //console.warn('⚠️ remoteVideosGrid를 찾을 수 없음');
            return;
        }

        // userId로 사용자 이름 찾기
        const userInfo = remoteUserInfo.get(userId);
        const userName = userInfo ? userInfo.userName : userId;

        // data-username 속성으로 비디오 아이템 찾기
        const videoItem = remoteVideosGrid.querySelector(`[data-username="${userName}"]`);
        if (videoItem) {
            videoItem.remove();
            //console.log('✅ 원격 비디오 제거 완료:', userName, userId);
            scwin.addChatMessage("시스템", `${userName}님의 영상 연결이 종료되었습니다.`, false);
        } else {
            //console.warn('⚠️ 제거할 비디오를 찾을 수 없음:', userName, userId);
        }

        // pendingIceCandidates 정리
        if (pendingIceCandidates.has(userId)) {
            pendingIceCandidates.delete(userId);
            //console.log('✅ 대기 ICE 후보 정리:', userId);
        }

    } catch (error) {
        //console.error('❌ 원격 사용자 제거 실패:', error);
    }
};

